(() => {
  const panel = document.querySelector('[data-send-queue]');
  if (!panel) throw new Error('the queued message is not shown');
  // Closed by default, like the phone's: the header line carries the count and
  // the promise, and the rows are one press away.
  if (panel.querySelectorAll('[data-queue-item]').length !== 0) throw new Error('the queue drew its rows without being asked');
  const toggle = panel.querySelector('[data-queue-toggle]');
  if (!toggle) throw new Error('the queue header is not a control');
  if (toggle.getAttribute('aria-expanded') !== 'false') throw new Error('the closed queue does not say so');
  toggle.click();
  return 'closed by default, then opened';
})()

(() => {
  const panel = document.querySelector('[data-send-queue]');
  if (panel.querySelectorAll('[data-queue-item]').length !== 1) throw new Error('the panel does not hold one row');
  if (!(panel.innerText || '').includes('顺便把图注也改成中文')) throw new Error('the row does not carry the held message');
  if (panel.querySelector('[data-queue-toggle]').getAttribute('aria-expanded') !== 'true') throw new Error('the opened queue does not say so');
  if (!document.querySelector("button[aria-label='停止并发送队列中的消息']")) throw new Error('the interrupt control does not say the queue goes with it');
  return 'one row, stop-and-send named';
})()

(() => {
  // The phone keeps each conversation's draft across page loads, so a capture that
  // only adds text inherits what the previous one typed. Clear it first.
  const box = document.querySelector('[aria-label="给 FutureOS 发消息"]');
  box.focus();
  const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
  setter.call(box, '');
  box.dispatchEvent(new Event('input', { bubbles: true }));
  return 'draft cleared';
})()

(() => {
  const choose = document.querySelector("[aria-label='选择如何处理这条消息']");
  if (!choose) throw new Error('a draft during a run offers no queue choice');
  if (document.querySelector("[aria-label='停止']")) throw new Error('a draft during a run still offers only Stop');
  return 'choice offered';
})()

(() => {
  const body = document.body.innerText || '';
