(() => {
  const box = document.querySelector('[aria-label="给 FutureOS 发消息"]');
  if ((box.value || '') !== '顺便把图注也改成中文') throw new Error('the refused sentence was dropped: ' + JSON.stringify(box.value));
  const panel = document.querySelector('[data-testid=send-queue]');
  if (!panel) throw new Error('the fixture queue left when a send was refused');
  const rows = panel.querySelectorAll('[data-testid=send-queue-item]').length;
  if (rows !== 0) throw new Error('a refused hand-over drew ' + rows + ' rows');
  if (!panel.innerText.includes('2 条等待中')) throw new Error('a refused hand-over changed the queue: ' + JSON.stringify(panel.innerText));
  const choose = document.querySelector("[aria-label='选择如何处理这条消息']");
  if (!choose) throw new Error('the refusal stopped the run: the composer no longer offers the send choice');
  return 'refused: sentence kept, queue unchanged, run still going';
})()

